package com.example.dashboard.delivery;
import com.auth0.jwt.*;import com.auth0.jwt.algorithms.*;import com.auth0.jwt.exceptions.*;import jakarta.persistence.*;import java.time.*;import java.util.*;import org.springframework.beans.factory.annotation.*;import org.springframework.data.jpa.repository.*;import org.springframework.http.*;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/delivery") class DeliveryController{
 private final DeliveryRepo orders;private final Algorithm jwt;private final KafkaTemplate<String,String> kafka;private final String serviceKey;DeliveryController(DeliveryRepo o,@Value("${app.jwt.secret}")String s,@Value("${app.service.key}")String key,KafkaTemplate<String,String>k){orders=o;jwt=Algorithm.HMAC256(s);serviceKey=key;kafka=k;}record Incoming(Long orderId,Long userId,String itemsJson,String paymentStatus){}record View(Long orderId,String paymentStatus,String status,List<StatusEvent> history){}
 private Long user(String a){if(a==null||!a.startsWith("Bearer "))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);try{return Long.valueOf(JWT.require(jwt).withIssuer("dashboard-auth").build().verify(a.substring(7)).getSubject());}catch(JWTVerificationException|NumberFormatException e){throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);}}
 private void admin(String a){if(a==null||!a.startsWith("Bearer "))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);try{if(!"ADMIN".equals(JWT.require(jwt).withIssuer("dashboard-auth").build().verify(a.substring(7)).getClaim("role").asString()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);}catch(JWTVerificationException e){throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);}}
 record AdminDeliveryUpdate(Long userId,String paymentStatus,String status,boolean acknowledged){}
 @GetMapping("/admin/orders") List<DeliveryOrder> adminOrders(@RequestHeader(value="Authorization",required=false)String a){admin(a);return orders.findAll();}
 @PutMapping("/admin/orders/{id}") DeliveryOrder editOrder(@RequestHeader(value="Authorization",required=false)String a,@PathVariable Long id,@RequestBody AdminDeliveryUpdate in){admin(a);DeliveryOrder order=orders.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(in.userId()==null||in.paymentStatus()==null||in.paymentStatus().isBlank()||in.status()==null||in.status().isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST);order.userId=in.userId();order.paymentStatus=in.paymentStatus().trim();order.status=in.status().trim();order.acknowledged=in.acknowledged();order.manualOverride=true;order.history.add(new StatusEvent(order.status));DeliveryOrder saved=orders.save(order);publish(saved);return saved;}
 @PostMapping("/orders") DeliveryOrder receive(@RequestHeader(value="X-Service-Key",required=false)String key,@RequestBody Incoming in){if(!serviceKey.equals(key))throw new ResponseStatusException(HttpStatus.FORBIDDEN);if(in.orderId()==null||in.userId()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST);DeliveryOrder d=orders.findByOrderId(in.orderId()).orElseGet(DeliveryOrder::new);d.orderId=in.orderId();d.userId=in.userId();d.itemsJson=in.itemsJson();d.paymentStatus=Optional.ofNullable(in.paymentStatus()).orElse("Payment successful");if(d.status==null){d.status="Ordered";d.history.add(new StatusEvent("Ordered"));}DeliveryOrder saved=orders.save(d);publish(saved);return saved;}
 @GetMapping("/orders/{orderId}") View order(@RequestHeader(value="Authorization",required=false)String a,@PathVariable Long orderId){Long u=user(a);DeliveryOrder d=orders.findByOrderId(orderId).filter(x->x.userId.equals(u)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));return new View(d.orderId,d.paymentStatus,d.status,d.history);}
 @PostMapping("/orders/{orderId}/acknowledge") void acknowledge(@RequestHeader(value="Authorization",required=false)String a,@PathVariable Long orderId){Long u=user(a);DeliveryOrder d=orders.findByOrderId(orderId).filter(x->x.userId.equals(u)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));d.acknowledged=true;if("Delivered".equals(d.status))orders.delete(d);else orders.save(d);}
 @Scheduled(initialDelay=20000,fixedDelay=30000) @Transactional void progress(){List<String>s=List.of("Ordered","Processing","Packed","Out for delivery","Delivered");for(DeliveryOrder d:orders.findByStatusNot("Delivered")){if(Boolean.TRUE.equals(d.manualOverride))continue;int i=s.indexOf(d.status);d.status=s.get(Math.min(i+1,s.size()-1));d.history.add(new StatusEvent(d.status));publish(d);}}
 private void publish(DeliveryOrder d){try{kafka.send("order-status",String.format("{\"orderId\":%d,\"userId\":%d,\"status\":\"%s\"}",d.orderId,d.userId,d.status));}catch(Exception ignored){/* Database remains the reliable delivery-status source when Kafka is offline. */}}
}
@Entity class DeliveryOrder{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)public Long id;@Column(unique=true)public Long orderId;public Long userId;@Column(length=20000)public String itemsJson;public String paymentStatus;public String status;public boolean acknowledged;public Boolean manualOverride;@OneToMany(cascade=CascadeType.ALL,orphanRemoval=true)public List<StatusEvent>history=new ArrayList<>();}@Entity class StatusEvent{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)public Long id;public String status;public Instant changedAt=Instant.now();StatusEvent(){}StatusEvent(String s){status=s;}}interface DeliveryRepo extends JpaRepository<DeliveryOrder,Long>{Optional<DeliveryOrder>findByOrderId(Long id);List<DeliveryOrder>findByStatusNot(String status);}
